// Aşk ölçeri: iki pada birlikte dokununca seviye yükselir.
// RGB mavi->yeşil->kırmızı olur, buzzer tizleşir, en üstte zafer ezgisi.
const int PAD1 = 2;
const int PAD2 = 3;
const int KIRMIZI = 9;
const int YESIL = 10;
const int MAVI = 11;
const int BUZZER = 5;

int seviye = 0;        // 0..100
bool zaferCalindi = false;

void renkVer(int s) {
  // 0 mavi, 50 yeşil, 100 kırmızı.
  int r, g, b;
  if (s < 50) { r = 0; g = s * 5; b = (50 - s) * 5; }
  else { r = (s - 50) * 5; g = (100 - s) * 5; b = 0; }
  analogWrite(KIRMIZI, r);
  analogWrite(YESIL, g);
  analogWrite(MAVI, b);
}

void zafer() {
  int notalar[] = {523, 659, 784, 1047};
  for (int i = 0; i < 4; i++) { tone(BUZZER, notalar[i], 120); delay(140); }
  noTone(BUZZER);
}

void setup() {
  Serial.begin(9600);
  pinMode(PAD1, INPUT_PULLUP);
  pinMode(PAD2, INPUT_PULLUP);
  pinMode(KIRMIZI, OUTPUT);
  pinMode(YESIL, OUTPUT);
  pinMode(MAVI, OUTPUT);
  Serial.println("Iki pada birlikte dokun.");
}

void loop() {
  bool dokunuluyor = digitalRead(PAD1) == LOW && digitalRead(PAD2) == LOW;

  if (dokunuluyor && seviye < 100) seviye++;
  else if (!dokunuluyor && seviye > 0) seviye -= 2;
  seviye = constrain(seviye, 0, 100);

  renkVer(seviye);

  if (dokunuluyor && seviye < 100) {
    tone(BUZZER, 200 + seviye * 9);  // tizleşir
  } else if (seviye >= 100 && !zaferCalindi) {
    Serial.println("Ask isisi: %100!");
    zafer();
    zaferCalindi = true;
  } else if (!dokunuluyor) {
    noTone(BUZZER);
  }
  if (seviye < 100) zaferCalindi = false;

  delay(30);
}
